create policy staff_insert_candidates on public.candidates for insert to authenticated with check (exists(select 1 from public.profiles p join public.exam_sessions e on e.id=exam_session_id where p.id=auth.uid() and p.center_id=e.center_id and p.role in ('admin','front_office')));
create policy staff_update_candidates on public.candidates for update to authenticated using (exists(select 1 from public.profiles p join public.exam_sessions e on e.id=exam_session_id where p.id=auth.uid() and p.center_id=e.center_id and p.role in ('admin','front_office'))) with check (exists(select 1 from public.profiles p join public.exam_sessions e on e.id=exam_session_id where p.id=auth.uid() and p.center_id=e.center_id and p.role in ('admin','front_office')));
grant insert, update on public.candidates to authenticated;
